    static long findOrder(long a, long p) {
        // Find the multiplicative order of a modulo p.
        // The order divides p-1. Factor p-1 and check divisors.
        long phi = p - 1;
        // Factorize phi
        List<Long> factors = new ArrayList<>();
        long temp = phi;
        for (long i = 2; i * i <= temp; i++) {
            if (temp % i == 0) {
                factors.add(i);
                while (temp % i == 0) {
                    temp /= i;
                }
            }
        }
        if (temp > 1) {
            factors.add(temp);
        }

        long order = phi;
        for (long f : factors) {
            while (order % f == 0 && modPow(a, order / f, p) == 1) {
                order /= f;
            }
        }
        return order;
    }

    static long modPow(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    static long modInverse(long a, long p) {
        // p is prime, so use Fermat's little theorem: a^(p-2) mod p
        return modPow(a, p - 2, p);
    }
