        long aMod = a % p;
        powVal[0] = 1;
        valToExps.computeIfAbsent(1, k -> new ArrayList<>()).add(0);
        for (int j = 1; j < pInt - 1; j++) {
            powVal[j] = (int) ((powVal[j-1] * aMod) % p);
            valToExps.computeIfAbsent(powVal[j], k -> new ArrayList<>()).add(j);
        }

