        // Check if target is in valToExps.
        // For each j in valToExps[target], solve CRT.

        long count = 0;
        long bMod = b % p;

        for (int i = 1; i < pInt; i++) {
            // Compute i^{-1} mod p
            long invI = modInverse(i, p);
            long target = (bMod * invI) % p;
            if (target < 0) target += p;
            target = (int) target;

            List<Integer> exps = valToExps.get(target);
            if (exps == null) continue;

            for (int j : exps) {
                // Solve r ≡ i (mod p) and r ≡ j (mod p-1)
                // r = i + p * t
                // i + p*t ≡ j (mod p-1)
                // p*t ≡ j - i (mod p-1)
                // Since p ≡ 1 (mod p-1), we have t ≡ j - i (mod p-1)
                // So t = (j - i) mod (p-1), and r = i + p * t
                // But we need r in [1, L].

                long diff = j - i;
                long t = diff % (p - 1);
                if (t < 0) t += (p - 1);
                long r = i + p * t;
                // r should be in [1, L]
                // i is in [1, p-1], t is in [0, p-2], so r is in [1, (p-1) + p*(p-2)] = [1, p^2 - 3p + 1]
                // L = p*(p-1) = p^2 - p
                // So r <= p^2 - 3p + 1 < p^2 - p = L for p >= 2.
                // And r >= 1.
                // So r is in [1, L].

                // Count n in [1, x] such that n ≡ r (mod L)
                // n = r + k*L, k >= 0
                // r + k*L <= x
                // k <= (x - r) / L
                // Number of such k: if x < r, then 0. Else floor((x - r) / L) + 1.

                if (r <= x) {
                    long kMax = (x - r) / L;
                    count += kMax + 1;
                }
            }
        }

        System.out.println(count);
    }

    static long modInverse(long a, long p) {
        // Extended Euclidean algorithm
        long[] res = extendedGCD(a, p);
        long x = res[1];
        x = (x % p + p) % p;
        return x;
    }

    static long[] extendedGCD(long a, long b) {
        if (b == 0) {
            return new long[]{a, 1, 0};
        }
        long[] res = extendedGCD(b, a % b);
        long g = res[0];
        long x1 = res[1];
        long y1 = res[2];
        long x = y1;
        long y = x1 - (a / b) * y1;
        return new long[]{g, x, y};
    }
